window.docContents[155].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Progress":{"contents":"\n\nThe progress theorem tells us that closed, well-typed\nterms are not stuck.\n\n\n\ntheorem progress (t : Tm) (τ : Ty) (hτ : <{ ∅ ⊢ ~t ⦂ ~τ }>) :\n    t.IsValue ∨ ∃ t', t ⟶ t' := by\n  generalize hΓ : (∅ : Context) = Γ at hτ\n  induction hτ with\n  | var Γ x τ₁ h =>\n    subst hΓ\n    -- Contradictory: variables cannot be typed in an empty context.\n    rw [PartialMap.getElem_empty] at h\n    cases h\n  | abs => left; constructor\n  | tru => left; constructor\n  | fls => left; constructor\n  | app Γ τ₁ τ₂ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n    -- `t = t₁ t₂`.  Proceed by cases on whether `t₁` is a value or steps.\n    subst hΓ\n    right\n    cases ih₁ rfl with\n    | inl hv₁ =>\n      cases ih₂ rfl with\n      | inl hv₂ =>\n        obtain ⟨x, u, rfl⟩ := canonical_forms_fun t₁ _ _ h₁ hv₁\n        exists <{ [~x := ~t₂] ~u }>\n        constructor\n        assumption\n      | inr hs₂ =>\n        obtain ⟨t₂', h⟩ := hs₂\n        exists <{ ~t₁ ~t₂' }>\n        constructor <;> assumption\n    | inr hs₁ =>\n      obtain ⟨t₁', h⟩ := hs₁\n      exists <{ ~t₁' ~t₂ }>\n      constructor <;> assumption\n  | ite Γ t₁ t₂ t₃ τ₁ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n    subst hΓ\n    right\n    cases ih₁ rfl with\n    | inl hv₁ =>\n      cases canonical_forms_bool t₁ h₁ hv₁ with\n      | inl he =>\n        subst he\n        exists t₂\n        constructor\n      | inr he =>\n        subst he\n        exists t₃\n        constructor\n    | inr hs₁ =>\n      obtain ⟨t₁', h⟩ := hs₁\n      exists <{ if ~t₁' then ~t₂ else ~t₃ }>\n      constructor\n      assumption\n\n\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC","header":"6.2. Progress","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Progress"}});